listPapos = value["listPapos"]

if not listPapos:
	return "Total: 0 | Sin Iniciar: 0 | En proceso: 0 | Finalizado: 0 | Revisado: 0"

total = len(listPapos)
sinIniciar = 0
enProceso = 0
finalizado = 0
revisado = 0

for papo in listPapos:
	status = papo.get("status")
	if status == "Sin Iniciar" or status is None:
		sinIniciar += 1
	elif status == "En proceso":
		enProceso += 1
	elif status == "Finalizado":
		finalizado += 1
	elif status == "Revisado":
		revisado += 1

return "Total: {} | Sin Iniciar: {} | En proceso: {} | Finalizado: {} | Revisado: {}".format(
	total, sinIniciar, enProceso, finalizado, revisado
)

